mapper.select:
SELECT ROW_NUMBER() OVER (ORDER BY FAQ_ID DESC) rownum, FAQ_ID, FAQ_CTGRY_CD, TITLE, SBST, SHOW_YN, TOP5_YN, A.REG_DT, A.REGR, COALESCE(B.CD_NM,'') AS FAQ_CTGRY_CD_NM FROM KOA_TB_FAQ A LEFT OUTER JOIN KOA_TB_COMN_CD B ON (A.FAQ_CTGRY_CD = B.COMN_CD AND B.GROUP_CD = 'FAQCAT1000') WHERE SHOW_YN = 'Y'
AND (UPPER(TITLE) LIKE '%' + UPPER(#{searchKeyword}) + '%' OR UPPER(SBST) LIKE '%' + UPPER(#{searchKeyword}) + '%')
AND FAQ_CTGRY_CD = #{faqCtgryCd}

SELECT COUNT(*) AS TOTCNT FROM KOA_TB_FAQ WHERE SHOW_YN = 'Y'
AND (UPPER(TITLE) LIKE '%' + UPPER(#{searchKeyword}) + '%' OR UPPER(SBST) LIKE '%' + UPPER(#{searchKeyword}) + '%')
AND FAQ_CTGRY_CD = #{faqCtgryCd}

mapper.update:
UPDATE KOA_TB_FAQ
SET RETV_NUM = (SELECT COALESCE(RETV_NUM, 0)+1 FROM KOA_TB_FAQ  WHERE FAQ_ID = #{faqId})
WHERE FAQ_ID = #{faqId}
